// 波形640枚
window.MAKI_WAVE_B64 = '';

// ── 展開 ─────────────────────────────────────────────
// 索引：'小-大' → 図番（1〜640）
window.MAKI_IDX = (function(){
  var o = {};
  window.MAKI_IDX_STR.split('|').forEach(function(part){
    var seg = part.split(':'), a = seg[0], b0 = parseInt(seg[1]);
    seg[2].split(',').forEach(function(g, i){ o[a + '-' + (b0 + i)] = parseInt(g); });
  });
  return o;
})();

// 波形：図番 → [{age, hi, lo}]　hi/lo は0〜100点に換算済み
window.MAKI_WAVE = (function(){
  var nums = [];
  window.MAKI_RUNS.split(',').forEach(function(s){
    var m = s.split('-');
    if (m.length === 2) { for (var i = parseInt(m[0]); i <= parseInt(m[1]); i++) nums.push(i); }
    else nums.push(parseInt(m[0]));
  });
  var bin = atob(window.MAKI_WAVE_B64), out = {}, p = 0;
  nums.forEach(function(g){
    var rows = [];
    for (var a = window.MAKI_AGE_START; a <= window.MAKI_AGE_END; a++) {
      var hi = bin.charCodeAt(p++) - window.MAKI_OFF;
      var lo = bin.charCodeAt(p++) - window.MAKI_OFF;
      rows.push({ age: a, hi: 50 + hi / 2, lo: 50 + lo / 2 });
    }
    out[g] = rows;
  });
  return out;
})();

// 記号ペアの2数値から図を引く。必ず昇順に並べ替えてから引く。
window.makiLookup = function(vA, vB){
  var lo = Math.min(vA, vB), hi = Math.max(vA, vB), key = lo + '-' + hi;
  var g = window.MAKI_IDX[key];
  if (g === undefined) return { status: '不収録', key: key };            // 原典に該当なし
  var rows = window.MAKI_WAVE[g];
  if (!rows)           return { status: '未取得', key: key, graph: g };  // 波形がまだ読めていない
  return { status: 'ok', key: key, graph: g, rows: rows };
};
